// inkMinContrast is the DEFAULT contrast target for a derived ink. It is not
// the WCAG AA floor and must never be set below it -- see inkFloorContrast.
//
// OWNER RULING 2026-08-14: 5.0, not the bare 4.5 AA floor.
//
// (warning block: THIS REVERSES A DOCUMENTED TECHNICAL DECISION, AND THE
// ARGUMENT AGAINST IT IS GOOD -- quoted, then answered)
const inkMinContrast = 5.0

// inkFloorContrast is the WCAG AA floor for normal-size body text, and the
// hard lower bound on anything inkPolicy will accept. A config that asks for
// less is refused, not honoured.
const inkFloorContrast = 4.5
const inkCeilingContrast = 7.0

// in pickInkOn, deliberately the FLOOR and not the target:
if ratio >= inkFloorContrast {
    return val, "palette:" + key
}

type inkPolicy struct {
    enabled  bool
    minRatio float64
}

func buildLegibleInkDefaults(css string, palette map[string]string, policy inkPolicy, logger *zap.Logger) string {
    if !policy.enabled {
        logger.Warn("buildLegibleInkDefaults: DISABLED by config -- emitting no ink companions", ...)
        return ""
    }
    ...
    hex, src := legibleInkFor(w.src, w.grounds, palette, policy.minRatio)
}

// config keys, all live DB config (agent_definitions):
//   legible_ink_enabled            bool     global kill (default true)
//   legible_ink_disabled_site_ids  []string per-site kill
//   legible_ink_min_contrast       float64  CLAMPED to [4.5, 7.0], clamp logged

// drives the REAL emitter at a NON-default target and requires the output to move
cases := []struct{ ratio float64; wantPrimaryInk string }{
    {inkFloorContrast, "#8a97bd"}, // what shipped 08-14 morning
    {5.0, "#94a0c2"},              // what the ruling produces
}
